ng either note: select o.observation_id, o.surface_form from observed_terms o join term_adjudications a using (observation_id) where a.outcome=''DEFERRED'' order by 1.', "updated_at" = '2026-09-25 05:07' WHERE "gap_id" = 'GAP-033';

